    if(age>=29)return{key:'PEAK',label:'PEAK YEARS',tone:'peak',copy:'Development is limited; maintaining level and fitness matters more now.'};
    if(gap<=0)return{key:'PLATEAU',label:'PLATEAUING',tone:'plateau',copy:'The player is close to the current development ceiling.'};
