    if(key==='manager-gamble')return squad.filter(p=>Number(p.age||99)<=21&&Number(p.potential||0)>=Number(p.ovr||0)+4).sort((a,b)=>Number(b.potential||0)-Number(a.potential||0)||Number(a.age||99)-Number(b.age||99))[0]||squad.filter(p=>Number(p.age||99)<=22).sort((a,b)=>Number(a.age||99)-Number(b.age||99))[0]||null;
    const user=pcPlayer();
    if(key==='player-shirt')return squad.filter(p=>p.id!==user?.id&&p.role===user?.role).sort((a,b)=>Number(b.ovr||0)-Number(a.ovr||0))[0]||squad.filter(p=>p.id!==user?.id).sort((a,b)=>Number(b.ovr||0)-Number(a.ovr||0))[0]||null;
    if(key==='player-dressing')return squad.filter(p=>p.id!==user?.id).sort((a,b)=>(Number(b.captain)-Number(a.captain))||Number(b.age||0)-Number(a.age||0)||Number(b.ovr||0)-Number(a.ovr||0))[0]||null;
