  function v108ThreadTransferClub(player,forPlayerCareer=false){
    if(!player||!currentClub)return null;
    const candidates=clubs.filter(club=>club.id!==currentClub.id&&getSquad(club).length<AI_SENIOR_SQUAD_CAP).map(club=>{
      const range=rangeFromOvr(club.ovr),level=(range[0]+range[1])/2,budget=moneyNumber(club.budget),value=livingPlayerMarketValue(player),fit=100-Math.abs(level-Number(player.ovr||0))*7+(forPlayerCareer?Math.max(0,divisionLevel(currentClub)-divisionLevel(club))*8:0)+(budget>=value?12:0)+(hashString(`${worldSeed}-V108-TARGET-${player.id}-${club.id}`)%11);return{club,fit,budget};
    }).filter(row=>forPlayerCareer||row.budget>=Math.min(livingPlayerMarketValue(player)*.72,2_000_000)).sort((a,b)=>b.fit-a.fit||a.club.name.localeCompare(b.club.name));
    return candidates[0]?.club||clubs.find(club=>club.id!==currentClub.id)||null;
  }
