    const offerGrid=$('#jobOfferGrid'),activeOffers=managerMarket.offers.filter(o=>o.status==='OPEN'&&o.type==='JOB'),interviewApps=managerMarket.applications.filter(a=>a.status==='INTERVIEW'),vacancies=activeManagerVacancies().filter(v=>managerClubInterestScore(clubById(v.clubId))>=24).slice(0,4);
