  function v37RepairLegacyPromises(){
    if(!currentClub)return;
    for(const pr of playerPromises){
      if(pr.status!=='active'||pr.type!=='PLAYING_TIME'||pr.participationVersion===37)continue;
      const p=careerPlayerById(pr.playerId);pr.participationVersion=37;
      if(!p||p.clubId!==currentClub.id){pr.status='cancelled';continue;}
      pr.clubId=currentClub.id;
      const history=recentClubFixtures(currentClub,40).filter(f=>f.type!=='FRIENDLY'&&f.date>pr.createdDate);
      pr.processedFixtureIds=history.map(f=>f.fixtureId);
      pr.startsDelivered=Math.max(Number(pr.startsDelivered||0),history.filter(f=>v37Participation(p,currentClub,f).started).length);
      if(pr.startsDelivered>=pr.targetStarts)v37ResolvePlayingTimePromise(pr,p,currentCareerISO());
    }
  }
  function evaluatePlayerPromisesAfterMatch(fixture){
    if(!fixture?.played||!currentClub||fixture.type==='FRIENDLY'||![fixture.homeClubId,fixture.awayClubId].includes(currentClub.id))return;
    for(const pr of playerPromises.filter(x=>x.status==='active'&&x.type==='PLAYING_TIME')){
      const p=careerPlayerById(pr.playerId);
      if(!p||p.clubId!==currentClub.id||(pr.clubId&&pr.clubId!==currentClub.id)){pr.status='cancelled';continue;}
      if(fixture.date<pr.createdDate||(pr.processedFixtureIds||[]).includes(fixture.fixtureId))continue;
      const row=v37Participation(p,currentClub,fixture);
      pr.processedFixtureIds=[...(pr.processedFixtureIds||[]),fixture.fixtureId].slice(-64);pr.participationVersion=37;
      if(!row.eligible){pr.pausedReason='Unavailable for selection';continue;}
      pr.pausedReason=null;pr.startsDelivered=Number(pr.startsDelivered||0)+(row.started?1:0);
      pr.matchesRemaining=Math.max(0,Number(pr.matchesRemaining||0)-1);
      if(pr.startsDelivered>=pr.targetStarts||pr.matchesRemaining===0)v37ResolvePlayingTimePromise(pr,p,fixture.date);
    }
    v37RefreshPlayingTimeDecisions();
  }
