  function maybeGenerateShortlistInterest(date=currentCareerISO()){
    if(!isTransferWindowOpen(date)||!transferShortlist.size)return null;
    if((hashString(`${worldSeed}-SHORTLIST-INTEREST-DAY-${date}`)%100)>18)return null;
    const candidates=[...transferShortlist].map(transferPlayerById).filter(p=>p&&!p.freeAgent&&effectiveKnowledge(p)>=35&&otherClubInterestFor(p).count>0&&!transferResponsePendingForPlayer(p.id));
    if(!candidates.length)return null;
    const p=candidates[hashString(`${worldSeed}-SHORTLIST-INTEREST-PICK-${date}`)%candidates.length],rec=recruitmentIntelRecord(p,true);
    if(rec.lastInterestDate&&Math.abs(diffDaysISO(rec.lastInterestDate,date))<18)return null;
    rec.lastInterestDate=date;
    const interest=otherClubInterestFor(p),buyerPool=clubs.filter(c=>c.id!==currentClub?.id&&c.id!==p.club?.id&&Math.abs(divisionLevel(c)-divisionLevel(p.club))<=1);
    const watcher=buyerPool.length?buyerPool[hashString(`${worldSeed}-SHORTLIST-WATCHER-${date}-${p.id}`)%buyerPool.length]:null;
    const who=watcher?watcher.name:`${interest.count} rival club${interest.count===1?'':'s'}`;
    addCareerInboxMessage({id:`shortlist-interest-${p.id}-${date}`,type:'TRANSFERS',sender:'RECRUITMENT TEAM',subject:`Interest grows in ${p.name}`,preview:`${who} are now monitoring your shortlisted target.`,title:`Your target is attracting attention`,body:[`${who} have increased their interest in ${p.name}.`,`There is no bid yet, but the recruitment team recommend completing your scouting work if the player remains a priority.`],signoff:recruitmentStaffProfile().name,action:{label:'OPEN TRANSFERS',route:'transfers'},date});
    return{playerId:p.id,playerName:p.name,watcher:who};
  }

