    featureEl.innerHTML=`<article class="vm-news-paper v33-editorial is-${escapeHtml(meta.publication.style)}">
      <header class="vm-news-masthead"><div class="vm-news-brand-lockup"><span>${escapeHtml(meta.desk)}</span><h1>${escapeHtml(meta.publication.name)}</h1><small>${escapeHtml(meta.publication.motto)}</small></div><div class="vm-news-edition"><b>${escapeHtml(String(selected.category||'NEWS').toUpperCase())}</b><span>${escapeHtml(meta.dateline)}</span><small>${article.readingMinutes} MIN READ · ${article.wordCount} WORDS</small></div></header>
      <section class="vm-news-cinema">${scene?`<img class="vm-news-cinema-bg" src="${escapeHtml(scene)}" alt="">`:''}<div class="vm-news-cinema-shade"></div><div class="vm-news-cinema-copy"><div class="vm-news-kickers"><span class="vm-news-chip">${escapeHtml(meta.world.toUpperCase())}</span><span class="vm-news-chip is-alt">${escapeHtml(meta.publication.style.toUpperCase())}</span><span class="vm-news-chip is-source">${escapeHtml(meta.sourceLabel)}</span></div><h2>${escapeHtml(selected.title)}</h2><p class="vm-news-deck">${escapeHtml(meta.deck)}</p><div class="vm-news-byline"><div class="vm-news-reporter-avatar">${avatarHTML(meta.reporterImage,meta.reporter.name)}</div><div><strong>${escapeHtml(meta.reporter.name)}</strong><span>${escapeHtml(meta.reporter.role)} · ${escapeHtml(meta.reporter.specialism||'GENERAL')}</span><small>${escapeHtml(meta.accessLabel)} · RELIABILITY ${Math.round(Number(meta.reporter.reliability||70))}/100</small></div></div></div><div class="vm-news-subject-stage"><div class="vm-news-subject-glow"></div>${heroHTML}<span>${escapeHtml(focus?.name||meta.world)}</span></div></section>
      <div class="vm-news-ticker"><span>LIVE CAREER FILE</span><b>${escapeHtml(shortDateLabel(selected.date||currentCareerISO()).toUpperCase())}</b><i></i><strong>${escapeHtml(String(selected.category||'NEWS').toUpperCase())}</strong><i></i><em>${escapeHtml(meta.publication.short)}</em></div>
      <section class="vm-news-content"><main class="vm-news-article-body">${sections}<footer class="vm-news-article-end"><span>END OF REPORT</span><strong>${escapeHtml(meta.reporter.name)} · ${escapeHtml(meta.publication.short)}</strong></footer></main><aside class="vm-news-sidebar-notes"><div class="vm-news-side-title"><span>STORY FILE</span><strong>AT A GLANCE</strong></div><ul class="vm-news-fact-list">${storyFacts}</ul><div class="vm-news-note"><span>PUBLICATION</span><strong>${escapeHtml(meta.publication.short)}</strong><small>${escapeHtml(meta.publication.motto)}</small></div><div class="vm-news-note"><span>WORLD</span><strong>${escapeHtml(meta.world)}</strong></div><div class="vm-news-note"><span>FOCUS CLUB</span><strong>${escapeHtml(focus?.name||'WORLD GAME')}</strong></div><div class="vm-news-note"><span>FILED FROM</span><strong>${escapeHtml(meta.desk)}</strong></div>${related?`<div class="vm-news-related"><span>ALSO IN THIS FILE</span>${related}</div>`:''}${meta.pullQuote?`<div class="vm-news-keyline"><span>KEY LINE</span><p>${escapeHtml(meta.pullQuote)}</p></div>`:''}</aside></section>
    </article>`;
    listEl.querySelectorAll('[data-news-story]').forEach(btn=>btn.addEventListener('click',()=>renderCareerNewsOverlayStories(stories,btn.dataset.newsStory,fallbackClub)));
    queueAvatarHydration(root);
