  function renderCentralCalendarMini(){
    const target=$('#centralCalendarMini');
    if(!target)return;
    initializeCareerCalendar(false);
    const today=currentCareerDate();
    const weekday=(today.getUTCDay()+6)%7;
    const startOffset=-weekday;
    const days=Array.from({length:14},(_,i)=>{
      const offset=startOffset+i;
      const iso=addDaysISO(currentCareerISO(),offset);
      const d=dateFromISO(iso);
      const event=centralAdvanceEventFor(d);
      return{d,iso,offset,event};
    });
    const month=today.toLocaleString('en-GB',{month:'short',year:'numeric',timeZone:'UTC'}).toUpperCase();
    target.innerHTML=`
      <div class="central-mini-meta"><strong>${month}</strong><span>NEXT 2 WEEKS</span></div>
      <div class="central-mini-week">${['M','T','W','T','F','S','S'].map(x=>`<span>${x}</span>`).join('')}</div>
      <div class="central-mini-days">${days.map(({d,iso,offset,event})=>{
        const isToday=offset===0;
        const outMonth=d.getUTCMonth()!==today.getUTCMonth();
        const classes=[isToday?'is-today':'',outMonth?'is-out-month':'',event.type==='match'?'has-match':event.type==='scout'?'has-scout':event.type==='deadline'?'has-deadline':event.type==='transfer'?'has-transfer':event.type==='board'?'has-board':event.type==='youth'?'has-youth':event.type==='contract'?'has-contract':event.type==='medical'?'has-medical':event.type==='training'?'has-training':''].filter(Boolean).join(' ');
        const marker=event.type==='match'?'M':event.type==='scout'?'SC':event.type==='deadline'?'DL':event.type==='transfer'?'TR':event.type==='board'?'BD':event.type==='youth'?'YA':event.type==='contract'?'CT':event.type==='medical'?'MD':event.type==='training'?'PF':'';
        const title=event.type==='match'?`${event.home?.name||''} v ${event.away?.name||''}`:event.label||longDateLabel(iso);
        return `<button type="button" class="${classes}" data-central-calendar-date="${iso}" title="${escapeHtml(title)}"><b>${d.getUTCDate()}</b>${marker?`<small>${marker}</small>`:''}</button>`;
      }).join('')}</div>`;
    $$('#centralCalendarMini [data-central-calendar-date]').forEach(btn=>btn.addEventListener('click',()=>{
      selectedCalendarDate=btn.dataset.centralCalendarDate;
      seasonCalendarCursor=`${selectedCalendarDate.slice(0,7)}-01`;
      seasonActiveTab='calendar';
      goCareerScreen('season');
    }));
  }

  function centralBriefingCopy(club,opponent,nextFixture,objectives=[]){
    const ownRow=leagueRowForClub(club),oppRow=leagueRowForClub(opponent);
    const confidence=ensureBoardConfidence();
    const morale=squadMoraleLabel(club);
    const gap=nextFixture?Math.max(0,diffDaysISO(currentCareerISO(),nextFixture.date)):null;
    const tactics=careerPreferences?.tactics||{};
    const objective=objectives[0]||null;
    const userHome=fixtureClubs(nextFixture).home?.id===club.id;
    let title='Keep the momentum alive';
    if(gap===0)title='Matchday is here';
    else if((oppRow?.pos||99)<(ownRow?.pos||99))title='A major test is coming';
    else if(confidence>=80&&['Happy','Very Happy'].includes(morale))title='The mood around the club is strong';
    const bodyParts=[
      ownRow?`${club.name} sit ${ordinal(ownRow.pos)} in ${club.division} with ${plural(ownRow.pts,'point')}.`:`${club.name} are preparing for the next challenge.`,
      opponent&&oppRow?`${opponent.name} arrive ${ordinal(oppRow.pos)} in their table picture.`:`${opponent?.name||'The opposition'} are next on the schedule.`,
      gap===0?'Everything is in place — this is now a live matchday.' : gap===1?'There is just one day left to sharpen the details.' : gap!=null?`${plural(gap,'day')} remain before kick-off.`:'The schedule is still being finalised.',
      objective?`Board focus remains ${objective.title.toLowerCase()} — currently ${objective.status.toLowerCase()}.`:null,
      `Current tactical identity: ${tactics.defensive||'Balanced'} without the ball, ${tactics.attacking||'Balanced'} with the ball, ${tactics.mentality||'Balanced'} mentality.`
    ].filter(Boolean);
    return {title,body:bodyParts.join(' '),context:`${userHome?'HOME FIXTURE':'AWAY FIXTURE'} · ${morale.toUpperCase()} MORALE · ${confidence}/100 BOARD CONFIDENCE`};
  }


  // ---------- V20.7.3: Career Pacing & Seasonal Variety ----------
