      state.seasonId=careerTime.seasonId;state.seenMomentKeys=[];state.pendingMoment=null;state.lastPhaseKey=null;state.lastCheckpointDate=null;state.lastWindowPulseDate=null;
      const first=v2073UserLeagueFixtures()[0];if(currentClub&&first&&currentCareerISO()<=first.date)state.pendingMoment={key:`${careerTime.seasonId}:${currentClub.id}:NEW_SEASON`,kind:'NEW_SEASON',date:currentCareerISO()};
