  function v65TaskCategoryProfile(task={}){const category=String(task.category||'').toUpperCase(),route=String(task.route||'');let key='club';if(['TRANSFERS','LOANS'].includes(category)||['transfer-offer','loan-offer'].includes(route))key='transfer';else if(category==='CONTRACTS'||route==='contracts')key='contract';else if(['MEDICAL','INJURY'].includes(category)||route==='squad'&&category==='MEDICAL')key='medical';else if(['BOARD','BOARD OBJECTIVE'].includes(category)||route==='board')key='board';else if(['REGISTRATION','ADMIN','CLUB EVENT'].includes(category))key='admin';else if(['SCOUTING','RECRUITMENT'].includes(category)||route==='scouting')key='scouting';else if(['DISCIPLINE','DISCIPLINARY'].includes(category))key='discipline';else if(['DRESSING ROOM','ACADEMY','SQUAD','PLAYER FUTURE'].includes(category)||['player','youth'].includes(route))key='squad';else if(['MANAGER CAREER','DECISION'].includes(category)||['manager-career','manager-offer','manager-interview','decision'].includes(route))key='career';else if(['NEW SEASON','PRE-SEASON'].includes(category)||route==='preseason')key='season';return{key,label:category||'CLUB'};}
