    careerDecisionEvents=[];playerPromises=[];careerEventCooldowns={};careerThreads=normalizeCareerThreadsState({});aiTransferHistory=[];developmentSnapshots={};negotiationEngine=normalizeNegotiationEngineState({});careerRuntime={boardConfidence:null,lastBoardConfidenceDate:null,lastDevelopmentMonth:null,lastAiTransferDate:null,lastLivingNewsDate:null};unexpectedEvents=normalizeUnexpectedEventsState({});cupRuntime={roundByes:{}};
