    const club=currentClub||selectedClub||clubById(ed.championClubId);
    const home=clubById(fixture.homeClubId),away=clubById(fixture.awayClubId),winnerId=championsCrownFixtureWinnerId(fixture);
    const r={saved:true,fixture,home,away,homeScore:Number(fixture.homeScore||0),awayScore:Number(fixture.awayScore||0),resultCode:winnerId===club?.id?'W':'L',opponent:home?.id===club?.id?away:home,resultMoment:matchResultMomentData({saved:true,fixture,resultCode:winnerId===club?.id?'W':'L'})};
