  function managerClubInterestScore(club){
    if(!club)return 0;
    const rep=Number(roadToGlory.managerReputation||18),desired=managerDesiredReputation(club),totals=roadToGlory.managerCareerTotals||{};
    const achievement=Number(totals.promotions||0)*3+Number(totals.leagueTitles||0)*5+Number(totals.domesticCups||0)*4+Number(totals.continentalCups||0)*9;
    const local=Math.min(8,playerManagerWorldExperience(clubWorldName(club))*2),tierExp=Math.min(6,playerManagerTierExperience(club.tier)*2);
    const employedPenalty=employmentStatus==='employed'&&currentClub?.id!==club.id?-2:0;
    const fit=(careerPreferences?.tactics?.mentality==='Attacking'&&clubWorldName(club)==='Ezuraya')?3:(careerPreferences?.tactics?.defensive==='Press'&&clubWorldName(club)==='Kharova')?4:0;
    return clamp(Math.round(54+(rep-desired)*1.35+achievement+local+tierExp+fit+employedPenalty),0,100);
  }
  function managerInterestLabel(score){const v=Number(score||0);return v>=82?'VERY HIGH':v>=67?'HIGH':v>=50?'MEDIUM':v>=32?'LOW':'NONE';}
  function managerSuitabilityLabel(club){const s=managerClubInterestScore(club);return s>=76?'EXCELLENT MATCH':s>=60?'GOOD MATCH':s>=44?'POSSIBLE':s>=28?'AMBITIOUS MOVE':'UNLIKELY';}
  function managerPreferredStyleForClub(club){
    const world=clubWorldName(club),options=world==='Kharova'?['HIGH PRESS','DIRECT','BALANCED']:world==='Caldria'?['POSSESSION','DEFENSIVE','BALANCED']:world==='Ezuraya'?['POSSESSION','HIGH PRESS','YOUTH-FIRST']:['BALANCED','COUNTER','POSSESSION'];
    return options[hashString(`${worldSeed}-CLUB-MANAGER-STYLE-${club.id}`)%options.length];
  }

  const MANAGER_ARCHETYPES=['BUILDER','PRAGMATIST','INNOVATOR','DEVELOPER','MOTIVATOR','TACTICIAN','FIREFIGHTER'];
  const MANAGER_TEMPERAMENTS=['CALM','DEMANDING','CHARISMATIC','RESERVED','INTENSE','METHODICAL'];
  const MANAGER_MEDIA_STYLES=['DIPLOMATIC','STRAIGHT-TALKING','GUARDED','BOLD','ANALYTICAL'];
  function enrichAiManagerIdentity(manager,club){
    if(!manager)return manager;club=club||clubById(manager.currentClubId)||clubs[0];
    const seed=`${worldSeed}-MANAGER-IDENTITY-${manager.id}`;
    const rng=mulberry32(hashString(seed));
    manager.archetype=manager.archetype||MANAGER_ARCHETYPES[Math.floor(rng()*MANAGER_ARCHETYPES.length)];
    manager.temperament=manager.temperament||MANAGER_TEMPERAMENTS[Math.floor(rng()*MANAGER_TEMPERAMENTS.length)];
    manager.mediaStyle=manager.mediaStyle||MANAGER_MEDIA_STYLES[Math.floor(rng()*MANAGER_MEDIA_STYLES.length)];
    manager.ambition=Number.isFinite(Number(manager.ambition))?Number(manager.ambition):clamp(38+Math.floor(rng()*58),20,96);
    manager.loyalty=Number.isFinite(Number(manager.loyalty))?Number(manager.loyalty):clamp(32+Math.floor(rng()*61),18,96);
    manager.adaptability=Number.isFinite(Number(manager.adaptability))?Number(manager.adaptability):clamp(35+Math.floor(rng()*58),20,96);
    manager.youthTrust=Number.isFinite(Number(manager.youthTrust))?Number(manager.youthTrust):clamp((manager.archetype==='DEVELOPER'?68:32)+Math.floor(rng()*31),18,96);
    manager.pressurePhase=manager.pressurePhase||'NONE';
    manager.lastReputationUpdateMonth=manager.lastReputationUpdateMonth||null;
    manager.careerRecord=manager.careerRecord&&typeof manager.careerRecord==='object'?manager.careerRecord:{matches:0,wins:0,draws:0,losses:0};
    manager.honours=manager.honours&&typeof manager.honours==='object'?manager.honours:{titles:0,promotions:0,cups:0};
    manager.history=Array.isArray(manager.history)?manager.history:[];
    manager.tacticalProfile=normalizeAiTacticalProfile(manager.tacticalProfile||deriveAiManagerTacticalProfile(manager,club));
    ensureAiManagerAppearanceProfile(manager,manager.currentClubId===club?.id?club:null);
    return manager;
  }
  // V20.7.4 — FC26-style AI Club Intelligence & Manager Tactical Identity.
  // The human manager keeps the existing simple tactics controls. This layer only governs AI clubs.
  function normalizeAiTacticalProfile(value={}){
    const src=value&&typeof value==='object'?value:{};
    const defensive=['Balanced','Press','Drop Back'].includes(src.defensive)?src.defensive:'Balanced';
    const attacking=['Balanced','Fast Break','Possession','Direct'].includes(src.attacking)?src.attacking:'Balanced';
    const mentality=['Defensive','Balanced','Attacking'].includes(src.mentality)?src.mentality:'Balanced';
    return{defensive,attacking,mentality};
  }
  function deriveAiManagerTacticalProfile(manager,club){
    manager=manager||{};club=club||clubById(manager.currentClubId)||clubs[0];
    const preferred=String(manager.preferredStyle||managerPreferredStyleForClub(club)||'BALANCED').toUpperCase();
    const archetype=String(manager.archetype||'TACTICIAN').toUpperCase();
    let profile={defensive:'Balanced',attacking:'Balanced',mentality:'Balanced'};
    if(preferred.includes('PRESS'))profile={defensive:'Press',attacking:'Fast Break',mentality:'Attacking'};
    else if(preferred.includes('POSSESSION'))profile={defensive:'Balanced',attacking:'Possession',mentality:'Balanced'};
    else if(preferred.includes('DIRECT'))profile={defensive:'Balanced',attacking:'Direct',mentality:'Balanced'};
    else if(preferred.includes('DEFENSIVE'))profile={defensive:'Drop Back',attacking:'Balanced',mentality:'Defensive'};
    else if(preferred.includes('COUNTER'))profile={defensive:'Drop Back',attacking:'Fast Break',mentality:'Balanced'};
    else if(preferred.includes('YOUTH'))profile={defensive:'Balanced',attacking:'Possession',mentality:'Balanced'};
    if(archetype==='FIREFIGHTER')profile={defensive:'Drop Back',attacking:preferred.includes('POSSESSION')?'Possession':'Direct',mentality:'Defensive'};
    else if(archetype==='DEVELOPER')profile={...profile,attacking:'Possession',mentality:'Balanced'};
    else if(archetype==='INNOVATOR')profile={defensive:'Press',attacking:'Possession',mentality:'Attacking'};
    else if(archetype==='MOTIVATOR'&&profile.mentality==='Balanced')profile.mentality='Attacking';
    else if(archetype==='PRAGMATIST'&&profile.mentality==='Attacking')profile.mentality='Balanced';
    else if(archetype==='TACTICIAN'&&preferred==='BALANCED'){
      const roll=hashString(`${worldSeed}-TACTICIAN-PROFILE-${manager.id||club?.id}`)%3;
      if(roll===0)profile={defensive:'Press',attacking:'Balanced',mentality:'Balanced'};
      if(roll===1)profile={defensive:'Balanced',attacking:'Possession',mentality:'Balanced'};
      if(roll===2)profile={defensive:'Drop Back',attacking:'Fast Break',mentality:'Balanced'};
    }
    return normalizeAiTacticalProfile(profile);
  }
  function aiManagerTacticalProfile(manager,club){
    if(!manager)return normalizeAiTacticalProfile();
    if(!manager.tacticalProfile)manager.tacticalProfile=deriveAiManagerTacticalProfile(manager,club);
    else manager.tacticalProfile=normalizeAiTacticalProfile(manager.tacticalProfile);
    return manager.tacticalProfile;
  }
  function aiTacticalProfileLabel(profile){
    profile=normalizeAiTacticalProfile(profile);return `${profile.defensive.toUpperCase()} · ${profile.attacking.toUpperCase()} · ${profile.mentality.toUpperCase()}`;
  }
  function aiTacticalProfileShort(profile){
    profile=normalizeAiTacticalProfile(profile);return `${profile.defensive} / ${profile.attacking} / ${profile.mentality}`;
  }
  function aiDesiredRoleCounts(profile){
    profile=normalizeAiTacticalProfile(profile);let out={ATTACKER:3,PLAYMAKER:3,DEFENDER:3,'ALL-ROUNDER':3};
    if(profile.mentality==='Attacking'){out.ATTACKER++;out.DEFENDER=Math.max(2,out.DEFENDER-1);}
    if(profile.mentality==='Defensive'){out.DEFENDER++;out.ATTACKER=Math.max(2,out.ATTACKER-1);}
    if(profile.attacking==='Possession'){out.PLAYMAKER++;out['ALL-ROUNDER']=Math.max(2,out['ALL-ROUNDER']-1);}
    if(profile.attacking==='Direct'||profile.attacking==='Fast Break'){out.ATTACKER++;out.PLAYMAKER=Math.max(2,out.PLAYMAKER-1);}
    if(profile.defensive==='Press'){out['ALL-ROUNDER']++;out.DEFENDER=Math.max(2,out.DEFENDER-1);}
    if(profile.defensive==='Drop Back'){out.DEFENDER++;out['ALL-ROUNDER']=Math.max(2,out['ALL-ROUNDER']-1);}
    return out;
  }
  function aiClubRawStrength(club){
    const squad=getSquad(club).filter(p=>!p.onLoan||p.clubId===club.id).sort((a,b)=>Number(b.ovr||0)-Number(a.ovr||0));const top=squad.slice(0,STARTER_SLOTS);return top.length?top.reduce((s,p)=>s+Number(p.ovr||60),0)/top.length:60;
  }
