      const date=addDaysISO(list.map(f=>f.date).sort().at(-1),7),home=winners[0],away=winners[1];
      const f={fixtureId:`PO_${careerTime.seasonId.replace('-','')}_${key}_FINAL_${home.abbr||home.id}_${away.abbr||away.id}`,competitionId:`playoff-${key}`,competitionName:`${home.division} Promotion Final`,round:'FINAL',playoffForDivision:key,date,homeClubId:home.id,awayClubId:away.id,played:false,homeScore:null,awayScore:null,type:'PLAYOFF'};
