  function prepareSeasonReview(){
    if(roadToGlory.seasonReview.pending||roadToGlory.seasonReview.completedSeasonId===careerTime.seasonId)return false;
    const data=buildSeasonReviewData();roadToGlory.seasonReview={pending:true,open:false,step:0,data,completedSeasonId:null};
    roadToGlory.playoffState.completed=true;
    const status=data.status;addCareerNews({id:`season-end-${careerTime.seasonId}-${currentClub.id}`,category:'SEASON REVIEW',title:`${currentClub.name.toUpperCase()} · ${status}`,body:[`${currentClub.name} finish ${ordinal(data.row?.pos||0)} in ${data.division}.`,`Manager season rating: ${data.grade.grade} · ${data.grade.label}.`],image:currentClub.badge,date:currentCareerISO()});
    if(status==='CHAMPIONS')showToast(`CHAMPIONS · ${currentClub.name}`);else if(status.includes('PROMOTION'))showToast(`PROMOTION SECURED · ${currentClub.name}`);else if(status==='RELEGATED')showToast(`RELEGATION CONFIRMED · ${currentClub.name}`);
    saveCareerState();return true;
  }
  function updateSeasonProgression(date=currentCareerISO()){
    roadToGlory=normalizeRoadToGloryState(roadToGlory);
    championsCrown=normalizeChampionsCrownState(championsCrown);
    ensureChampionsCrownProgression(date);
    if(roadToGlory.seasonReview.pending)return{important:{type:'SEASON_REVIEW',title:'Season Review'}};
    if(allLeagueFixturesComplete()&&!roadToGlory.playoffState.generated)generatePromotionPlayoffSemis();
    if(roadToGlory.playoffState.generated&&!roadToGlory.playoffState.finalsGenerated)generatePromotionPlayoffFinals();
    if(roadToGlory.playoffState.finalsGenerated&&playoffFixtures().every(f=>f.played)&&allCupFixturesComplete()&&allChampionsCrownCompleteForCurrentSeason()){
      if(currentClub){const final=playoffFixtures().find(f=>f.round==='FINAL'&&f.played&&(f.homeClubId===currentClub.id||f.awayClubId===currentClub.id));if(final){const won=(final.homeScore>final.awayScore?final.homeClubId:final.awayClubId)===currentClub.id,title=won?'PROMOTION SECURED':'PROMOTION DREAM ENDS',body=won?`${currentClub.name} have won the promotion final and will move up a tier next season.`:`${currentClub.name} have been beaten in the promotion final and remain in ${currentClub.division}.`;addCareerNews({id:`playoff-final-user-${careerTime.seasonId}-${currentClub.id}`,category:'PROMOTION FINAL',title:`${currentClub.name.toUpperCase()} · ${title}`,body:[body],image:currentClub.badge,date:currentCareerISO()});if(!careerInboxMessages.some(m=>m.id===`playoff-final-inbox-${careerTime.seasonId}-${currentClub.id}`)){addCareerInboxMessage({id:`playoff-final-inbox-${careerTime.seasonId}-${currentClub.id}`,type:'BOARD',sender:'BOARD OF DIRECTORS',subject:title,preview:body,title,body:[body],signoff:'Board of Directors',date:currentCareerISO()});showToast(`${title} · ${currentClub.name}`);}}}
      if(!currentClub&&employmentStatus==='unemployed'){
        const rollover=processUnemployedSeasonEnd();
        if(rollover?.rolled)return{important:{type:'NEW_SEASON',title:`${careerTime.seasonId} begins`,summary:'The world has rolled into a new season while you remain in the manager market.'}};
      }
      if(prepareSeasonReview())return{important:{type:'SEASON_REVIEW',title:'Season Review Ready'}};
    }
    return{important:null};
  }
  function projectedClubBudget(club,status){
    const current=Math.max(100000,moneyNumber(club.budget)),mult=status.includes('PROMOTION')||status==='CHAMPIONS'&&Number(club.tier||4)>1?1.34:status==='RELEGATED'?.78:status==='CHAMPIONS'?1.14:1.02;
    const noise=((hashString(`${worldSeed}-BUDGET-${careerTime.seasonId}-${club.id}`)%901)-450)/10000;return Math.max(100000,Math.round(current*clamp(mult+noise,.72,1.42)/10000)*10000);
  }
  function applyClubEvolution(data){
    const snapshot=data.plan?standingsSnapshot():standingsSnapshot(),plan=data.plan||seasonMovementPlan(snapshot);
    clubs.forEach(club=>{
      const row=(snapshot[club.divisionKey]||[]).find(r=>r.clubId===club.id);if(!row)return;const status=seasonStatusForClub(club,plan,row),st=rtgClubState(club);let delta=0;
      if(status==='CHAMPIONS')delta+=.16;if(status.includes('PROMOTION'))delta+=.18;if(status==='RELEGATED')delta-=.18;if(row.pos<=6)delta+=.04;if(row.pos>=16&&Number(club.tier||4)<4)delta-=.04;
      const base=Number(st.baseReputation||club.reputation||1),current=Number(st.reputation||club.reputation||1);const pull=(base-current)*.08;st.reputation=clamp(Number((current+delta+pull).toFixed(2)),1,5);club.reputation=st.reputation;
      const nextBudget=projectedClubBudget(club,status);club.budget=formatExactMoney(nextBudget);st.lastBudget=club.budget;
    });
  }
  function applyLeagueMovement(plan){
    Object.entries(plan.promoted||{}).forEach(([lowerKey,ids])=>{const lowerMeta=divisionMetaFor(lowerKey);if(!lowerMeta)return;const upper=rtgDivisionByWorldTier(lowerMeta.world,Number(lowerMeta.tier)-1);if(!upper)return;ids.forEach(id=>{const club=clubById(id);if(club){club.divisionKey=upper.key;club.division=upper.name;club.tier=upper.tier;const st=rtgClubState(club);st.divisionKey=upper.key;st.tier=upper.tier;}});});
    Object.entries(plan.relegated||{}).forEach(([upperKey,ids])=>{const upperMeta=divisionMetaFor(upperKey);if(!upperMeta)return;const lower=rtgDivisionByWorldTier(upperMeta.world,Number(upperMeta.tier)+1);if(!lower)return;ids.forEach(id=>{const club=clubById(id);if(club){club.divisionKey=lower.key;club.division=lower.name;club.tier=lower.tier;const st=rtgClubState(club);st.divisionKey=lower.key;st.tier=lower.tier;}});});
  }
  function updateClubExpectationsForNewSeason(){
    [...new Set(clubs.map(c=>c.divisionKey).filter(Boolean))].forEach(key=>{
      const pool=clubs.filter(c=>c.divisionKey===key).sort((a,b)=>backgroundClubStrength(b)-backgroundClubStrength(a)||Number(b.reputation||1)-Number(a.reputation||1));
      pool.forEach((club,index)=>{const rank=index+1,tier=Number(club.tier||4);if(tier===1)club.expectation=rank<=4?'Challenge for the title':rank<=8?'Push for continental qualification':rank<=13?'Finish in the top half':'Avoid relegation trouble';else club.expectation=rank<=3?'Win promotion':rank<=7?'Reach the promotion places':rank<=12?'Build steadily':'Avoid relegation';});
    });
  }
  function seasonCareerTotalsFromFixtures(club){const list=fixtures.filter(f=>f.played&&f.type!=='FRIENDLY'&&(f.homeClubId===club.id||f.awayClubId===club.id));let w=0,d=0,l=0;list.forEach(f=>{const home=f.homeClubId===club.id,a=home?f.homeScore:f.awayScore,b=home?f.awayScore:f.homeScore;if(a>b)w++;else if(a<b)l++;else d++;});return{matches:list.length,wins:w,draws:d,losses:l};}
  function recordSeasonCareerMemories(seasonId,snapshot=standingsSnapshot(),plan=seasonMovementPlan(snapshot)){
    if(!seasonId||!snapshot||!plan)return;const date=currentCareerISO();
    const seasonParticipants=club=>club?getSquad(club).filter(p=>Number(p.seasonStats?.apps||0)>0).map(p=>p.id):[];
    const managerTrophy=(club,competition,competitionId)=>{if(!club||club.id!==currentClub?.id)return;if(careerMemoryEventsForClub(club,'MAJOR').some(e=>e.type==='MANAGER_FIRST_TROPHY'&&e.metadata?.managerName===managerName))return;recordCareerMemory({type:'MANAGER_FIRST_TROPHY',clubId:club.id,date,seasonId,competitionId,importance:'MAJOR',key:`V42-MANAGER-FIRST-TROPHY-${club.id}-${managerMarket?.playerSpell?.startedDate||jobSearchState?.appointedDate||managerName}`,metadata:{managerName,competition}});};
    Object.entries(snapshot).forEach(([divisionKey,rows])=>rows.forEach(row=>{const club=clubById(row.clubId);if(!club)return;const status=seasonStatusForClub(club,plan,row),meta={competition:club.division,divisionKey,finish:Number(row.pos||0),points:Number(row.pts||0),status,tier:Number(club.tier||4)};
      if(plan.champions?.[divisionKey]===club.id){recordCareerMemory({type:'LEAGUE_TITLE',clubId:club.id,playerIds:seasonParticipants(club),date,seasonId,competitionId:divisionKey,importance:Number(club.tier||4)===1?'HISTORIC':'MAJOR',metadata:meta});managerTrophy(club,club.division,divisionKey);}
      if(Object.values(plan.promoted||{}).some(ids=>(ids||[]).includes(club.id)))recordCareerMemory({type:'PROMOTION',clubId:club.id,playerIds:seasonParticipants(club),date,seasonId,competitionId:divisionKey,importance:'MAJOR',metadata:meta});
      if(Object.values(plan.relegated||{}).some(ids=>(ids||[]).includes(club.id)))recordCareerMemory({type:'RELEGATION',clubId:club.id,playerIds:seasonParticipants(club),date,seasonId,competitionId:divisionKey,importance:'MAJOR',metadata:meta});
      const previous=(roadToGlory.clubHistory?.[club.id]||[]).filter(h=>h.seasonId!==seasonId&&h.divisionKey===divisionKey&&Number(h.finish)>0).map(h=>Number(h.finish));if(previous.length&&Number(row.pos||99)<Math.min(...previous))recordCareerMemory({type:'CLUB_RECORD',clubId:club.id,date,seasonId,competitionId:divisionKey,importance:'MAJOR',metadata:{...meta,recordType:'BEST_LEAGUE_FINISH',previousBest:Math.min(...previous)}});
    }));
    (roadToGlory.competitionHistory||[]).filter(h=>h.seasonId===seasonId).forEach(h=>{if(!h.championClubId)return;const winner=clubById(h.championClubId);if(h.type==='CUP'){recordCareerMemory({type:'CUP_WIN',clubId:h.championClubId,playerIds:seasonParticipants(winner),date,seasonId,competitionId:h.competitionId||h.competition,importance:'MAJOR',metadata:{competition:h.competition,world:h.world}});managerTrophy(winner,h.competition||'Domestic Cup',h.competitionId||h.competition);}else if(h.type==='CONTINENTAL'){recordCareerMemory({type:'CHAMPIONS_CROWN_WIN',clubId:h.championClubId,playerIds:seasonParticipants(winner),date,seasonId,competitionId:h.competitionId||'champions-crown',importance:'HISTORIC',metadata:{competition:h.competition||'Champions Crown',runnerUpClubId:h.runnerUpClubId||null}});managerTrophy(winner,h.competition||'Champions Crown',h.competitionId||'champions-crown');}});
    cupSeasonSnapshots().forEach(cup=>{if(cup.runnerUpClubId){const runner=clubById(cup.runnerUpClubId);recordCareerMemory({type:'CUP_FINAL',clubId:cup.runnerUpClubId,playerIds:seasonParticipants(runner),date,seasonId,competitionId:cup.competitionId,matchId:cup.fixtureId,importance:'NOTABLE',metadata:{competition:cup.competition,runnerUp:true,winnerClubId:cup.championClubId}});}});
  }
  function recordCompletedSeason(data){
    if(roadToGlory.careerHistory.some(h=>h.seasonId===data.seasonId&&h.clubId===data.clubId))return;
    const totals=seasonCareerTotalsFromFixtures(currentClub),cupFixtures=fixtures.filter(f=>f.type==='CUP'&&f.played&&(f.homeClubId===currentClub.id||f.awayClubId===currentClub.id)),entry={seasonId:data.seasonId,seasonNumber:data.seasonNumber,clubId:data.clubId,clubName:data.clubName,world:data.world,divisionKey:data.divisionKey,division:data.division,finish:data.row?.pos||null,status:data.status,continentalOutcome:data.continentalOutcome||championsCrownOutcomeForClub(data.clubId,championsCrownEdition(data.seasonId)),points:data.row?.pts||0,wins:data.row?.wins||0,draws:data.row?.draws||0,losses:data.row?.losses||0,gf:data.row?.gf||0,ga:data.row?.ga||0,grade:data.grade.grade,cupRound:cupFixtures.length?Math.max(...cupFixtures.map(f=>Number(f.round||1))):0,managerRepBefore:data.oldManagerRep,managerRepAfter:data.newManagerRep};
    roadToGlory.careerHistory.push(entry);roadToGlory.managerReputation=data.newManagerRep;jobSearchState.reputation=Math.max(Number(jobSearchState.reputation||0),data.newManagerRep);
    const mt=roadToGlory.managerCareerTotals;mt.matches+=totals.matches;mt.wins+=totals.wins;mt.draws+=totals.draws;mt.losses+=totals.losses;if(data.status.includes('PROMOTION')||(data.status==='CHAMPIONS'&&Number(data.tier||4)>1))mt.promotions++;if(data.status==='RELEGATED')mt.relegations++;if(data.status==='CHAMPIONS')mt.leagueTitles++;
    const snap=standingsSnapshot();Object.entries(snap).forEach(([key,rows])=>rows.forEach(row=>{const club=clubById(row.clubId);if(!club)return;(roadToGlory.clubHistory[club.id]||(roadToGlory.clubHistory[club.id]=[])).push({seasonId:data.seasonId,divisionKey:key,division:club.division,tier:Number(club.tier||4),finish:row.pos,points:row.pts,status:seasonStatusForClub(club,data.plan,row)});}));
    Object.entries(data.plan.champions||{}).forEach(([key,id])=>{const club=clubById(id);if(club)roadToGlory.competitionHistory.push({seasonId:data.seasonId,type:'LEAGUE',divisionKey:key,competition:club.division,championClubId:id,championClubName:club.name,world:clubWorldName(club)});});
    [...new Set(fixtures.filter(f=>f.type==='CUP').map(f=>f.competitionId))].forEach(compId=>{const cup=fixtures.filter(f=>f.type==='CUP'&&f.competitionId===compId&&f.played);if(!cup.length)return;const maxRound=Math.max(...cup.map(f=>Number(f.round||1))),finals=cup.filter(f=>Number(f.round||1)===maxRound);if(finals.length!==1)return;const f=finals[0],winner=clubById(knockoutFixtureWinnerId(f));if(!winner)return;roadToGlory.competitionHistory.push({seasonId:data.seasonId,type:'CUP',competitionId:compId,competition:f.competitionName,championClubId:winner.id,championClubName:winner.name,world:clubWorldName(winner)});if(winner.id===currentClub.id)mt.domesticCups++;});
    data.plan.qualifiers.forEach(q=>roadToGlory.championsCrownQualifications.push(q));
    recordSeasonCareerMemories(data.seasonId,snap,data.plan);recordWorldHistorySeason({...data,snapshot:snap});
    const milestone=(id,title)=>{if(!roadToGlory.milestones.some(m=>m.id===id)){roadToGlory.milestones.push({id,title,date:currentCareerISO(),seasonId:data.seasonId});addCareerNews({id:`milestone-${id}`,category:'MANAGER CAREER',title:`${managerName.toUpperCase()} · ${title}`,body:[`${managerName} has reached a new career milestone with ${currentClub.name}.`],image:currentClub.badge,date:currentCareerISO()});addCareerInboxMessage({id:`milestone-inbox-${id}`,type:'BOARD',sender:'CLUB SECRETARY',subject:title,preview:'A new manager career milestone has been recorded.',title,body:[`Your career archive now records: ${title}.`],signoff:'Club Secretary',date:currentCareerISO()});}};
    if(mt.promotions===1)milestone('first-promotion','FIRST CAREER PROMOTION');if(mt.leagueTitles===1)milestone('first-title','FIRST LEAGUE TITLE');if(mt.matches>=100)milestone('100-matches','100 MATCHES MANAGED');if(mt.wins>=50)milestone('50-wins','50 CAREER WINS');
  }
  function finalizeRoadToGlorySeason(data){recordCompletedSeason(data);applyClubEvolution(data);applyLeagueMovement(data.plan);if(currentClub){if(data.status.includes('PROMOTION')||(data.status==='CHAMPIONS'&&Number(data.tier||4)>1))getSquad(currentClub).forEach(p=>adjustPlayerMorale(p,1));if(data.status==='RELEGATED')getSquad(currentClub).filter(p=>['Crucial','Important'].includes(p.squadRole)).forEach(p=>adjustPlayerMorale(p,-1));}}

  function seasonReviewAwardCard(label,p){return p?`<article class="rtg-award-card v2072-award-card"><span>${escapeHtml(label)}</span><div>${avatarHTML(p.avatar,p.name)}</div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.role)} · ${p.apps} apps · ${plural(p.goals,'goal')}</p><b>${p.avgRating.toFixed(1)} AVG</b></article>`:`<article class="rtg-award-card is-empty v2072-award-card"><span>${escapeHtml(label)}</span><h3>NO ELIGIBLE PLAYER</h3></article>`;}
