    body.querySelectorAll('[data-career-replace-slot]').forEach(btn=>btn.addEventListener('click',()=>{careerSaveConfirm={type:'replace',slot:Number(btn.dataset.careerReplaceSlot)};renderCareerSaveMenu();}));
