      worldSeed=d.worldSeed;recruitmentDay=Number(d.recruitmentDay||1);careerSeason=Number(d.careerSeason||1);careerYear=Number(d.careerYear||2026);avatarOrder=null;fullAvatarOrder=null;
      const migratedDate=addDaysISO(`${careerYear}-08-01`,Math.max(0,recruitmentDay-1));
