      careerNewsStories=Array.isArray(d.careerNewsStories)?d.careerNewsStories:[];
      pendingNegotiations=Array.isArray(d.pendingNegotiations)?d.pendingNegotiations:[];
      careerDecisionEvents=Array.isArray(d.careerDecisionEvents)?d.careerDecisionEvents:[];
      playerPromises=Array.isArray(d.playerPromises)?d.playerPromises:[];
