      careerThreads=normalizeCareerThreadsState(d.careerThreads||{});
      aiTransferHistory=Array.isArray(d.aiTransferHistory)?d.aiTransferHistory:[];
      developmentSnapshots=d.developmentSnapshots&&typeof d.developmentSnapshots==='object'?d.developmentSnapshots:{};
      careerRuntime=d.careerRuntime&&typeof d.careerRuntime==='object'?{boardConfidence:null,lastBoardConfidenceDate:null,lastDevelopmentMonth:null,lastAiTransferDate:null,lastLivingNewsDate:null,...d.careerRuntime}:{boardConfidence:null,lastBoardConfidenceDate:null,lastDevelopmentMonth:null,lastAiTransferDate:null,lastLivingNewsDate:null};
      unexpectedEvents=normalizeUnexpectedEventsState(d.unexpectedEvents||{});
