  function renderOfficeManager(){
    initializeManagerMarketState();ensureCareerMarketVacancies(currentCareerISO());
    const club=currentClub||selectedClub||clubs[0],careerTotals=roadToGlory.managerCareerTotals||{},careerHonours=Number(careerTotals.leagueTitles||0)+Number(careerTotals.domesticCups||0)+Number(careerTotals.continentalCups||0),repScore=Math.round(Number(roadToGlory.managerReputation||0)),repLabel=managerRepLabel(repScore),contract=managerMarket.playerContract;
    const offers=managerMarket.offers.filter(o=>o.status==='OPEN'),interviews=managerMarket.applications.filter(a=>a.status==='INTERVIEW'),approaches=managerMarket.applications.filter(a=>a.status==='INTERVIEW'&&a.source==='APPROACH'),spell=managerMarket.playerSpell,spellRec=spell?playerSpellRecord(spell):null,security=employmentStatus==='employed'?playerJobSecurityScore():50,milestone=managerCareerNextRepMilestone(),standing=managerCareerStandingProfile(),form=managerCareerFormProfile();
    const headerClub=employmentStatus==='employed'?currentClub:null;
    const header=`<section class="mc-command-hero" style="--mc-club:${escapeHtml(headerClub?.accent||'#174f9f')}"><div class="mc-manager-stage">${managerPortraitHTML(ensureManagerProfile(),'mc-manager-paperdoll','office')}</div><div class="mc-manager-identity"><span>MANAGER CAREER · ${employmentStatus==='employed'?'IN POST':'AVAILABLE'}</span><h2>${escapeHtml(managerName)}</h2><p>${escapeHtml(managerCityName(ensureManagerProfile().nationId,ensureManagerProfile().cityId))}, ${escapeHtml(managerNationName(ensureManagerProfile().nationId))}</p><div><b>${escapeHtml(repLabel)}</b><small>${managerRepStars(repScore)}</small></div></div><div class="mc-command-status"><section><header><span>REPUTATION</span><strong>${repScore}/100</strong></header><div class="mc-command-meter"><i style="width:${repScore}%"></i></div><small>${milestone.remaining?`${plural(milestone.remaining,'point')} to ${escapeHtml(milestone.label)}`:'Highest reputation tier achieved'}</small></section><section><header><span>JOB SECURITY</span><strong>${employmentStatus==='employed'?`${security}/100`:'FREE AGENT'}</strong></header><div class="mc-command-meter is-security"><i style="width:${employmentStatus==='employed'?security:100}%"></i></div><small>${escapeHtml(managerMarketJobSecurity())} · driven by results and expectations</small></section></div><div class="mc-current-club">${headerClub?badgeHTML(headerClub):'<span class="manager-free-agent-mark">FREE</span>'}<small>${headerClub?'CURRENT CLUB':'CAREER STATUS'}</small><strong>${escapeHtml(headerClub?.name||'OPEN TO WORK')}</strong><span>${escapeHtml(headerClub?.division||'LIVE JOB MARKET')}</span></div></section><section class="mc-metric-ribbon"><div><span>CAREER RECORD</span><strong>${Number(careerTotals.wins||0)+(spellRec?.wins||0)}W · ${Number(careerTotals.draws||0)+(spellRec?.draws||0)}D · ${Number(careerTotals.losses||0)+(spellRec?.losses||0)}L</strong></div><div><span>CLUBS MANAGED</span><strong>${new Set([...managerMarket.spellHistory.map(s=>s.clubId),...(spell?[spell.clubId]:[])]).size}</strong></div><div><span>HONOURS</span><strong>${careerHonours}</strong></div><div><span>PROMOTIONS</span><strong>${Number(careerTotals.promotions||0)}</strong></div><div><span>LIVE APPROACHES</span><strong>${approaches.length}</strong></div><div><span>OPEN OFFERS</span><strong>${offers.length}</strong></div></section>`;
    const nav=`<nav class="manager-career-tabs"><button type="button" data-manager-career-view="career" class="${managerCareerView==='career'?'is-active':''}">YOUR CAREER</button><button type="button" data-manager-career-view="vacancies" class="${managerCareerView==='vacancies'?'is-active':''}">OPEN VACANCIES <i>${activeManagerVacancies().length}</i></button><button type="button" data-manager-career-view="interest" class="${managerCareerView==='interest'?'is-active':''}">CLUB INTEREST</button><button type="button" data-manager-career-view="contract" class="${managerCareerView==='contract'?'is-active':''}">CONTRACT ${offers.length?`<i>${offers.length}</i>`:''}</button></nav>`;
    let body='';
    if(managerCareerView==='vacancies')body=`<section class="manager-career-pane">${managerMarketVacanciesHTML()}</section>`;
    else if(managerCareerView==='interest')body=`<section class="manager-career-pane">${managerMonitoringHTML()}</section>`;
    else if(managerCareerView==='contract')body=`<section class="manager-career-pane">${managerContractHTML()}${offers.filter(o=>o.type==='JOB').length?`<div class="manager-active-offers"><span>ACTIVE JOB OFFERS</span>${offers.filter(o=>o.type==='JOB').map(o=>{const c=clubById(o.clubId);return c?`<article>${badgeHTML(c)}<div><small>${escapeHtml(c.division)}</small><strong>${escapeHtml(c.name)}</strong><span>${plural(o.contractYears,'year')} · £${Number(o.weeklySalary||0).toLocaleString('en-GB')}/wk</span></div><button type="button" data-manager-offer="${o.id}">REVIEW OFFER</button></article>`:'';}).join('')}</div>`:''}</section>`;
    else body=`<section class="manager-career-pane"><div class="mc-overview-lead"><article class="mc-mandate-card"><header><div><span>CURRENT MANDATE</span><h3>${headerClub?escapeHtml(headerClub.name):'BUILD YOUR NEXT CHAPTER'}</h3></div>${headerClub?`<b>${escapeHtml(managerMarketJobSecurity())}</b>`:'<b>AVAILABLE</b>'}</header>${headerClub?`<div class="mc-mandate-body"><div><span>BOARD EXPECTATION</span><strong>${escapeHtml(contract?.initialExpectation||headerClub.expectation||'Build steadily')}</strong><p>Your security reflects league position, recent form, board confidence and the time available in this spell.</p></div><aside><span>LEAGUE POSITION</span><strong>${escapeHtml(standing.label)}</strong><small>${form.label} from the last ${plural(form.form.length||0,'match','matches')}</small></aside></div>`:`<div class="mc-mandate-body"><div><span>CAREER STATUS</span><strong>Ready for interviews</strong><p>Your reputation, achievements and tactical fit determine which clubs will progress an application.</p></div><aside><span>MARKET ACCESS</span><strong>${activeManagerVacancies().length} live roles</strong><small>${plural(managerMonitoringClubs().length,'club')} currently above the monitoring threshold</small></aside></div>`}</article><article class="mc-opportunity-card"><span>CAREER OPPORTUNITIES</span><h3>${offers.filter(o=>o.type==='JOB').length?`${offers.filter(o=>o.type==='JOB').length} decision${offers.filter(o=>o.type==='JOB').length===1?'':'s'} waiting`:`${activeManagerVacancies().length} live vacancies`}</h3><p>${interviews.length} interview${interviews.length===1?'':'s'} ready · ${approaches.length} confidential approach${approaches.length===1?'':'es'} · ${plural(managerMonitoringClubs().length,'club')} monitoring</p><div><button type="button" data-manager-open-market>EXPLORE JOB MARKET</button>${offers.filter(o=>o.type==='JOB')[0]?`<button type="button" data-manager-offer="${offers.filter(o=>o.type==='JOB')[0].id}">REVIEW OFFER</button>`:''}</div></article></div>${managerCareerSignalsHTML()}<section class="mc-reputation-path"><div><span>NEXT REPUTATION MILESTONE</span><h3>${escapeHtml(milestone.label)}</h3><p>${milestone.remaining?`${plural(milestone.remaining,'point')} remaining. Results, overachievement, promotions and honours move your standing.`:'Your reputation has reached its highest tier.'}</p></div><strong>${repScore}<small>/100</small></strong><div class="mc-reputation-track"><i style="width:${milestone.progress}%"></i></div></section>${managerWorldPulseHTML()}${managerCareerTargetClubsHTML()}<section class="manager-spell-card"><div class="manager-pane-heading"><span>CAREER TIMELINE</span><h3>Clubs, records and defining chapters</h3><p>Every spell stays attached to its dates, results and reason for ending.</p></div>${managerCareerSpellsHTML()}</section>${managerRivalsHTML()}</section>`;
    $('#officeManagerContent').innerHTML=`${header}${nav}${body}`;
    $('#officeManagerContent').querySelectorAll('[data-manager-career-view]').forEach(b=>b.addEventListener('click',()=>{managerCareerView=b.dataset.managerCareerView;renderOfficeManager();}));
    $('#officeManagerContent').querySelector('[data-manager-open-market]')?.addEventListener('click',()=>{managerCareerView='vacancies';renderOfficeManager();});
    wireManagerMarketControls($('#officeManagerContent'));queueManagerHydration(document);
  }

