    const fixture=userFixtureOnDate(currentCareerISO());
    if(matchdayActionBusy||button?.disabled||!screens.matchday?.classList.contains('is-active'))return;
    if(!fixture){showToast('No playable fixture today');return;}
    if(fixture.played){showToast('This fixture has already been completed');return;}
    const lineupReady=prepareFixtureLineupsForMatchday(fixture,{repairUser:true,notify:true});if(!lineupReady.ready){showToast(lineupReady.message||'Select three eligible starters before continuing.');renderMatchday();return;}
    renderMatchday();
