  function clubLifeState(){if(!livingSquad?.clubLife||Number(livingSquad.clubLife.version||0)<3)livingSquad=normalizeLivingSquadState(livingSquad);return livingSquad.clubLife;}
  function v44ClubLifeFact(type,metadata={},date=currentCareerISO(),club=currentClub){
    if(!type||!club||!currentClub||club.id!==currentClub.id)return null;
    const state=clubLifeState(),safeDate=isoDate(date),m=metadata&&typeof metadata==='object'?metadata:{};
    const discriminator=[m.playerId||'',m.secondaryPlayerId||'',m.role||m.facility||'',m.threshold||m.level||'',m.milestone||''].join('|');
    const key=`V44-CLUB-LIFE-${type}-${club.id}-${careerTime.seasonId}-${discriminator}`;
    const existing=state.continuityFacts.find(f=>f.key===key);if(existing)return existing;
    const fact={id:livingSquadNextId('CLF'),key,type:String(type),date:safeDate,seasonId:careerTime.seasonId,clubId:club.id,playerId:m.playerId||null,secondaryPlayerId:m.secondaryPlayerId||null,role:m.role||null,facility:m.facility||null,threshold:Number.isFinite(Number(m.threshold))?Number(m.threshold):null,level:Number.isFinite(Number(m.level))?Number(m.level):null,assists:Number.isFinite(Number(m.assists))?Number(m.assists):null,familiarity:Number.isFinite(Number(m.familiarity))?Number(m.familiarity):null,consumed:false,consumedDate:null};
    state.continuityFacts.push(fact);state.continuityFacts=state.continuityFacts.slice(-180);return fact;
  }
  function v44ClubLifePendingFact(type,date=currentCareerISO()){
    const state=clubLifeState(),limits={FIRST_GOAL:56,ASSIST_10:56,ROLE_FAMILIARITY:84,FACILITY_UPGRADE:100,ACADEMY_PROMOTION:70},limit=limits[type]||70;
    return [...(state.continuityFacts||[])].reverse().find(f=>!f.consumed&&f.type===type&&f.clubId===currentClub?.id&&f.date<=date&&diffDaysISO(f.date,date)<=limit)||null;
  }
