  function clubLifeRelationship(a,b,type,date){if(!a||!b)return null;const state=clubLifeState(),key=clubLifePairKey(a,b),existing=state.relationships[key]||{playerIds:[a.id,b.id],type,score:0,since:date,sinceSeasonId:careerTime.seasonId,lastBeat:null,lastSeasonId:null,moments:0,milestones:[]};existing.type=type||existing.type;existing.score=clamp(Number(existing.score||0)+1,0,12);existing.moments=Math.max(0,Number(existing.moments||0))+1;existing.sinceSeasonId=existing.sinceSeasonId||careerTime.seasonId;existing.lastSeasonId=careerTime.seasonId;existing.lastBeat=date;existing.milestones=Array.isArray(existing.milestones)?existing.milestones.slice(-8):[];const mark=existing.score>=8?'ESTABLISHED':existing.score>=5?'DEVELOPING':existing.score>=3?'FORMING':null;if(mark&&!existing.milestones.includes(mark))existing.milestones.push(mark);state.relationships[key]=existing;return existing;}
